%dw 2.0
output application/json
---
if (vars.additionalValidate) {
	"status": "PASS",
	"getOrderOFSCResponse": {
		"actividyId": payload.Orden.ActivityId,
		"order": vars.orderNumber,
		"state": "started",
		"position": payload.Orden.Posicion,
		"aditionalData": payload.Orden.InformacionAdicional
	}
} else 
{
	"status": "PASS",
	"getOrderOFSCResponse": {
		"actividyId": payload.Orden.ActivityId,
		"order": vars.orderNumber,
		"state": payload.Orden.Estado,
		"position": payload.Orden.Posicion,
		"aditionalData": payload.Orden.InformacionAdicional
	}
}

%dw 2.0
output application/json
---
if (p('noRecords') as Boolean) 
{
	"status": "PASS",
	"getOrderOFSCResponse":{
		"activityId": "1",
		"order" : vars.orderNumber,
		"state": "started",
		"position": "1",
		"aditionalData":{
			"Nombre":"date",
			"Valor": (now() >> "America/Bogota") as String {format : "uuuu-MM-dd"}
		}
	}
}
else 
{
  "status": 500,
  "code": "GETORDENER02",
  "message": {
      "message": "Registro no encontrado"
  },
  "messageServer": "",
  "cause": [
      {
          "origin": app.name,
          "message": "org.mule.module.raiseException"
      }
  ]
}
